 try {
  if($type==='category_save'){ $name=trim($_POST['name']??''); if($name===''||mb_strlen($name)>100) throw new RuntimeException('Nama kategori wajib diisi (maksimal 100 karakter).'); if($id) $pdo->prepare('UPDATE categories SET name=? WHERE id=?')->execute([$name,$id]); else $pdo->prepare('INSERT INTO categories(name) VALUES(?)')->execute([$name]); flash('Kategori tersimpan.'); go('categories'); }
