  if($type==='category_delete'){ $pdo->prepare('DELETE FROM categories WHERE id=?')->execute([$id]); flash('Kategori dihapus.'); go('categories'); }
  if($type==='member_save'){ $v=[trim($_POST['member_no']??''),trim($_POST['name']??''),trim($_POST['email']??''),trim($_POST['phone']??''),trim($_POST['address']??'')]; if(!$v[0]||mb_strlen($v[0])>30||!$v[1]||mb_strlen($v[1])>120||!filter_var($v[2],FILTER_VALIDATE_EMAIL)||strlen($v[2])>160||strlen($v[3])>30||mb_strlen($v[4])>10000) throw new RuntimeException('Data anggota tidak valid atau terlalu panjang.'); if($id){$v[]=$id;$pdo->prepare('UPDATE members SET member_no=?,name=?,email=?,phone=?,address=? WHERE id=?')->execute($v);}else $pdo->prepare('INSERT INTO members(member_no,name,email,phone,address) VALUES(?,?,?,?,?)')->execute($v); flash('Anggota tersimpan.'); go('members'); }
  if($type==='member_delete'){ $pdo->prepare('DELETE FROM members WHERE id=?')->execute([$id]); flash('Anggota dihapus.'); go('members'); }
  if($type==='book_save'){ $title=trim($_POST['title']??''); $cat=(int)($_POST['category_id']??0); $stockValue=filter_var($_POST['stock']??null,FILTER_VALIDATE_INT); $stock=$stockValue===false||$stockValue===null?-1:$stockValue; $yearRaw=trim((string)($_POST['year']??'')); $year=$yearRaw===''?null:filter_var($yearRaw,FILTER_VALIDATE_INT); $isbn=trim((string)($_POST['isbn']??'')); $isbn=$isbn===''?null:$isbn; if(!$title||mb_strlen($title)>200||!$cat||$stock<0||($year!==null&&($year===false||$year<1000||$year>(int)date('Y')))||strlen($isbn??'')>30) throw new RuntimeException('Judul, kategori, stok, ISBN, atau tahun terbit tidak valid.'); $cover=null; if(!empty($_FILES['cover']['name'])){ if($_FILES['cover']['error']!==UPLOAD_ERR_OK||$_FILES['cover']['size']>MAX_UPLOAD_BYTES) throw new RuntimeException('Sampul gagal diunggah atau melebihi 2 MB.'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['cover']['tmp_name']); $image=@getimagesize($_FILES['cover']['tmp_name']); $ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null; if(!$ext||!$image||($image['mime']??'')!==$mime) throw new RuntimeException('Sampul harus berupa gambar JPG, PNG, atau WEBP yang valid.'); $cover=bin2hex(random_bytes(16)).'.'.$ext; if(!move_uploaded_file($_FILES['cover']['tmp_name'],UPLOAD_DIR.$cover)) throw new RuntimeException('Gagal menyimpan sampul.'); $uploadedCover=$cover; }
  $data=[$title,trim($_POST['author']??''),trim($_POST['publisher']??''),$year,$isbn,$cat,$stock,trim($_POST['description']??''),$cover]; $oldCover=null; if($id){$old=$pdo->prepare('SELECT cover FROM books WHERE id=?');$old->execute([$id]);$oldCover=$old->fetchColumn()?:null;$data[]=$id; $sql='UPDATE books SET title=?,author=?,publisher=?,publish_year=?,isbn=?,category_id=?,stock=?,description=?,cover=COALESCE(?,cover) WHERE id=?';}else $sql='INSERT INTO books(title,author,publisher,publish_year,isbn,category_id,stock,description,cover) VALUES(?,?,?,?,?,?,?,?,?)'; $pdo->prepare($sql)->execute($data); if($cover!==null&&$oldCover&&$oldCover!==$cover)remove_uploaded_cover($oldCover); flash('Buku tersimpan.'); go('books'); }
  if($type==='book_delete'){ $q=$pdo->prepare('SELECT cover FROM books WHERE id=?');$q->execute([$id]);$oldCover=$q->fetchColumn();$d=$pdo->prepare('DELETE FROM books WHERE id=?');$d->execute([$id]);if($d->rowCount()&&$oldCover)remove_uploaded_cover($oldCover);flash('Buku dihapus.');go('books'); }
