 } catch(Throwable $ex){ if($pdo->inTransaction())$pdo->rollBack(); if($uploadedCover)remove_uploaded_cover($uploadedCover); $message=($type==='borrow'&&$ex instanceof PDOException&&$ex->getCode()==='23000')?'Transaksi ini sudah diproses. Periksa riwayat peminjaman.':($ex instanceof PDOException?'Data gagal disimpan. Periksa duplikasi atau relasi data.':$ex->getMessage()); flash($message,'danger'); go($type==='password_change'?'password':($type==='category_save'||$type==='category_delete'?'categories':($type==='member_save'||$type==='member_delete'?'members':($type==='borrow'||$type==='return'?'loans':'books')))); }
