function remove_uploaded_cover(?string $cover): void { if($cover!==null&&preg_match('/^[a-f0-9]{32}\\.(jpg|png|webp)$/',$cover)){ $path=UPLOAD_DIR.$cover;if(is_file($path))@unlink($path); } }
function valid_iso_date(string $value): bool { $date=DateTimeImmutable::createFromFormat('!Y-m-d',$value); return $date!==false&&$date->format('Y-m-d')===$value; }
function count_sql(string $sql): int { $st=db()->prepare($sql);$st->execute();return (int)$st->fetchColumn(); }
