<?php
function render_loans(int $limit=0,?string $from=null,?string $to=null):void{
 $sql='SELECT b.*,m.name member,m.member_no,d.items,DATEDIFF(COALESCE(b.return_date,CURDATE()),b.due_date) late FROM borrowings b JOIN members m ON m.id=b.member_id JOIN (SELECT bd.borrowing_id,GROUP_CONCAT(CONCAT(bo.title," x",bd.quantity) SEPARATOR ", ") items FROM borrowing_details bd JOIN books bo ON bo.id=bd.book_id GROUP BY bd.borrowing_id) d ON d.borrowing_id=b.id';
 $where=[];$args=[];if($from&&$to){$where[]='b.borrow_date BETWEEN ? AND ?';$args=[$from,$to];}if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY b.id DESC';if($limit)$sql.=' LIMIT '.(int)$limit;$st=db()->prepare($sql);$st->execute($args);echo '<div class="table-responsive"><table class="table"><thead><tr><th>Anggota</th><th>Buku</th><th>Pinjam</th><th>Jatuh tempo</th><th>Kembali</th><th>Status</th><th>Keterlambatan</th><th></th></tr></thead><tbody>';foreach($st as $r){echo '<tr><td>'.e($r['member_no'].' � '.$r['member']).'</td><td>'.e($r['items']).'</td><td>'.e($r['borrow_date']).'</td><td>'.e($r['due_date']).'</td><td>'.e($r['return_date']??'-').'</td><td>'.e($r['status']).'</td><td>'.max(0,(int)$r['late']).' hari</td><td>';if($r['status']==='dipinjam')echo '<form method="post" action="?page=action"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="type" value="return"><input type="hidden" name="id" value="'.$r['id'].'"><button class="btn btn-sm btn-outline-primary">Kembalikan</button></form>';echo '</td></tr>';}echo '</tbody></table></div>';
}
function render_book_modal(array $cats):void{?><div class="modal fade" id="bookModal"><div class="modal-dialog modal-lg"><form class="modal-content" method="post" enctype="multipart/form-data" action="?page=action"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="book_save"><div class="modal-header"><h5>Tambah Buku</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body row g-3"><?php foreach(['title'=>'Judul','author'=>'Penulis','publisher'=>'Penerbit','year'=>'Tahun terbit','isbn'=>'ISBN','stock'=>'Stok'] as $n=>$label):?><div class="col-md-6"><label class="form-label"><?=$label?></label><input class="form-control" name="<?=$n?>" <?=$n==='stock'?'type="number" min="0" value="0"':($n==='year'?'type="number" min="1000" max="'.date('Y').'"':'')?>></div><?php endforeach?><div class="col-md-6"><label class="form-label">Kategori</label><select class="form-select" name="category_id" required><option value="">Pilih</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach?></select></div><div class="col-md-6"><label class="form-label">Sampul (maks. 2 MB)</label><input type="file" name="cover" class="form-control" accept="image/jpeg,image/png,image/webp"></div><div class="col-12"><label class="form-label">Deskripsi</label><textarea class="form-control" name="description" rows="3"></textarea></div></div><div class="modal-footer"><button class="btn btn-primary">Simpan Buku</button></div></form></div></div><?php }
